$inlineJs = iso_js();
$inlineJs .= <<<'JS'
$(function(){
  var currentImages=[],newFiles=[],galleryImages=[],galleryIndex=0;
  var photoInput=document.getElementById('ubiPhotoInput');
  function parseImages(value){if(Array.isArray(value))return value;if(!value)return[];try{return JSON.parse(value)}catch(e){return[]}}
  function imageUrl(image){return image.url||('../../api/activos/ubicaciones/imagen.php?id='+parseInt(image.IdImagen,10))}
  function activePhotoCount(){return currentImages.length-$('#ubiPhotoGrid .ubi-remove-existing:checked').length+newFiles.length}
  function updatePhotoCounter(){$('#ubiPhotoCounter').text(activePhotoCount()+' / 4')}
  function syncNewFiles(){var dt=new DataTransfer();newFiles.forEach(function(file){dt.items.add(file)});photoInput.files=dt.files}
  function openGallery(images,title,start){galleryImages=images||[];galleryIndex=Math.max(0,Math.min(parseInt(start||0,10),galleryImages.length-1));if(!galleryImages.length)return;$('#ubiGalleryTitle').text(title||'Ubicación');renderGallery();$('#modalUbicacionImagen').modal('show')}
  function renderGallery(){if(!galleryImages.length)return;var item=galleryImages[galleryIndex],url=imageUrl(item),mime=String(item.Mime||item.type||'').toLowerCase(),isPdf=mime==='application/pdf'||/\.pdf(?:$|\?)/i.test(url);$('#ubiOpenFile').attr('href',url);if(isPdf){$('#ubiGalleryImage').hide().removeAttr('src');$('#ubiGalleryPdf').show().attr('src',url+'#toolbar=1&navpanes=1&view=FitH')}else{$('#ubiGalleryPdf').hide().removeAttr('src');$('#ubiGalleryImage').show().attr('src',url)}$('#ubiGalleryPosition').text((galleryIndex+1)+' / '+galleryImages.length);$('#ubiGalleryPrev,#ubiGalleryNext').prop('disabled',galleryImages.length<2)}
  function renderPhotoGrid(){
    var grid=$('#ubiPhotoGrid').empty();
    currentImages.forEach(function(image,index){var isPdf=String(image.Mime||'').toLowerCase()==='application/pdf',card=$('<div class="ubi-photo-card"><button type="button" class="ubi-zoom" title="Abrir"></button><label class="ubi-photo-remove"><input type="checkbox" class="ubi-remove-existing" name="EliminarImagenes[]"> Retirar</label></div>');if(isPdf)card.addClass('ubi-pdf-card').prepend('<i class="fas fa-file-pdf"></i><span>PLANO PDF</span>');else card.prepend('<img alt="Fotografía guardada">').find('img').attr('src',imageUrl(image));card.find('input').val(image.IdImagen);card.find('.ubi-zoom').on('click',function(){openGallery(currentImages,'Archivos de la ubicación',index)});card.find('input').on('change',function(){card.css('opacity',this.checked?'.42':'1');updatePhotoCounter()});grid.append(card)});
    newFiles.forEach(function(file,index){var url=URL.createObjectURL(file),isPdf=file.type==='application/pdf'||/\.pdf$/i.test(file.name),card=$('<div class="ubi-photo-card ubi-photo-new"><button type="button" class="ubi-zoom" title="Abrir"></button><button type="button" class="ubi-remove-new" title="Quitar">&times;</button></div>');if(isPdf)card.addClass('ubi-pdf-card').prepend('<i class="fas fa-file-pdf"></i><span>NUEVO PDF</span>');else card.prepend('<img alt="Nueva fotografía">').find('img').attr('src',url);card.find('.ubi-zoom').on('click',function(){openGallery(newFiles.map(function(f){return{url:URL.createObjectURL(f),Mime:f.type,type:f.type}}),'Nuevos archivos',index)});card.find('.ubi-remove-new').on('click',function(){URL.revokeObjectURL(url);newFiles.splice(index,1);syncNewFiles();renderPhotoGrid()});grid.append(card)});
    if(!currentImages.length&&!newFiles.length)grid.append('<div class="ubi-photo-empty-note"><i class="far fa-file-image mr-1"></i>Esta ubicación todavía no tiene fotografías ni planos.</div>');
    updatePhotoCounter();
  }
  function resetPhotos(images){currentImages=parseImages(images);newFiles=[];if(photoInput)photoInput.value='';renderPhotoGrid()}
  $(photoInput).on('change',function(){var available=4-activePhotoCount(),rejected=false;Array.from(photoInput.files).forEach(function(file){var isPdf=file.type==='application/pdf'||/\.pdf$/i.test(file.name),isImage=['image/jpeg','image/png','image/webp'].includes(file.type),valid=(isPdf&&file.size<=20*1024*1024)||(isImage&&file.size<=8*1024*1024);if(!valid){rejected=true;return}if(available>0){newFiles.push(file);available--}else rejected=true});syncNewFiles();renderPhotoGrid();if(rejected)Swal.fire('Archivo no agregado','Use imágenes JPG, PNG o WEBP de máximo 8 MB, o PDF de máximo 20 MB. La galería admite hasta 4 archivos.','warning')});
  $(document).on('click','.btn-location-gallery',function(){var images=parseImages($(this).attr('data-images'));openGallery(images,$(this).attr('data-title')||'Ubicación',0)});
  $('#ubiGalleryPrev').on('click',function(){galleryIndex=(galleryIndex-1+galleryImages.length)%galleryImages.length;renderGallery()});
  $('#ubiGalleryNext').on('click',function(){galleryIndex=(galleryIndex+1)%galleryImages.length;renderGallery()});
  $('#modalUbicacionImagen').on('hidden.bs.modal',function(){$('#ubiGalleryImage,#ubiGalleryPdf').removeAttr('src');if($('#modalUbicacion').hasClass('show'))$('body').addClass('modal-open')});
  var table=$('#tblUbicaciones').DataTable({language:DATATABLES_SPANISH,pageLength:10,order:[],autoWidth:false,dom:'rt<"d-flex justify-content-between align-items-center flex-wrap p-3"lip>'});
  var roleTable=$('#tblRoles').DataTable({language:DATATABLES_SPANISH,pageLength:10,order:[],autoWidth:false,dom:'rt<"d-flex justify-content-between align-items-center flex-wrap p-3"lip>'});
  $('#isoSearch').on('input',function(){table.search(this.value).draw();roleTable.search(this.value).draw()});
  var f=$('#formUbicacion')[0];
  $('#btnNewLocation').on('click',function(){isoNew(f);f.elements.IdUbicacion.value=0;resetPhotos([]);$('#modalUbicacion .modal-title').text('Nueva ubicación');$('#modalUbicacion').modal('show')});
  $('.btn-edit-location').on('click',function(){var d=$(this).data('record');if(typeof d==='string')d=JSON.parse(d);isoFill(f,d);f.elements.IdUbicacion.value=d.IdUbicacion;if(f.elements.JustificacionCIA)f.elements.JustificacionCIA.value=d.JustificacionCIA||'';resetPhotos(d.Imagenes||[]);$('#modalUbicacion .modal-title').text('Editar ubicación');$('#modalUbicacion').modal('show')});
  var rf=$('#formRol')[0];
  $('#btnNewRole').on('click',function(){isoNew(rf);rf.elements.IdRol.value=0;$('#modalRol .modal-title').text('Nuevo rol clave');$('#modalRol').modal('show')});
  $('.btn-edit-role').on('click',function(){var d=$(this).data('record');if(typeof d==='string')d=JSON.parse(d);isoFill(rf,d);rf.elements.IdRol.value=d.IdRol;rf.elements.ProcesoRol.value=d.Proceso||'';rf.elements.DescripcionRol.value=d.Descripcion||'';rf.elements.PropietarioRol.value=d.Propietario||'';rf.elements.RequisitoLegalRol.value=d.RequisitoLegal||'';rf.elements.UbicacionLogicaRol.value=d.UbicacionLogica||'';rf.elements.ObservacionesRol.value=d.Observaciones||'';if(rf.elements.JustificacionCIA)rf.elements.JustificacionCIA.value=d.JustificacionCIA||'';$('#modalRol .modal-title').text('Editar rol clave');$('#modalRol').modal('show')});
  $(rf).find('[name="TitularActual"],[name="Suplente"]').on('input',function(){if($.trim(this.value)!=='')rf.elements.DatosPersonales.checked=true});
  // Asignación masiva (filtro propio para no perder filas del formulario)
  function filtrar(){var q=($('#eqFilter').val()||'').toLowerCase(),cat=$('#eqCat').val(),solo=$('#eqSolo').is(':checked');$('#tblEquipos tbody tr').each(function(){var r=$(this),ok=(!q||String(r.data('text')).indexOf(q)>-1)&&(!cat||r.data('cat')===cat)&&(!solo||String(r.data('sin'))==='1');r.toggle(ok)})}
  $('#eqFilter').on('input',filtrar);$('#eqCat,#eqSolo').on('change',filtrar);
  $('#eqAll').on('change',function(){var c=this.checked;$('#tblEquipos tbody tr:visible .eq-check').prop('checked',c)});
  $('#eqApply').on('click',function(){var v=$('#eqBulk').val();if(!v){alert('Seleccione primero una ubicación.');return}$('#tblEquipos tbody tr:visible').each(function(){if($(this).find('.eq-check').is(':checked'))$(this).find('.eq-loc').val(v)})});
  var hash=location.hash;if(hash&&$('.iso-tabs a[href="'+hash+'"]').length)$('.iso-tabs a[href="'+hash+'"]').tab('show');
  $('.iso-tabs a').on('shown.bs.tab',function(e){history.replaceState(null,'',e.target.getAttribute('href'));table.columns.adjust();roleTable.columns.adjust()});
});
JS;
